// ═══════════════════════════════════════════════════════════════════
// ENTERPRISE CORE ROUTER - INPUT VALIDATION & ENRICHMENT
// ═══════════════════════════════════════════════════════════════════

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Generate unique request ID
const requestId = body.request_id || `REQ-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

// Validate required fields
const errors = [];

if (!body.domain) {
  errors.push('Field "domain" is required');
}

if (!body.intent) {
  errors.push('Field "intent" is required');
}

if (errors.length > 0) {
  throw new Error(`Validation failed: ${errors.join(', ')}`);
}

// Normalize domain
const validDomains = ['comercial', 'leads', 'operations', 'finance', 'knowledge', 'monitoring'];
const normalizedDomain = body.domain.toLowerCase().trim();

if (!validDomains.includes(normalizedDomain)) {
  throw new Error(`Invalid domain: ${normalizedDomain}. Valid domains: ${validDomains.join(', ')}`);
}

// Map domain to sub-workflow
const domainMapping = {
  'comercial': { workflow: 'SW1_LEADS_COMERCIAL', priority: 'high' },
  'leads': { workflow: 'SW1_LEADS_COMERCIAL', priority: 'high' },
  'operations': { workflow: 'SW2_OPERACOES', priority: 'medium' },
  'finance': { workflow: 'SW3_FINANCEIRO', priority: 'high' },
  'knowledge': { workflow: 'SW4_CONHECIMENTO', priority: 'low' },
  'monitoring': { workflow: 'SW5_MONITORAMENTO', priority: 'critical' }
};

const routing = domainMapping[normalizedDomain];

// Extract client info
const clientInfo = {
  ip: headers['x-forwarded-for'] || headers['x-real-ip'] || 'unknown',
  userAgent: headers['user-agent'] || 'unknown',
  origin: headers['origin'] || headers['referer'] || 'unknown'
};

// Build enriched request
return {
  requestId: requestId,
  timestamp: new Date().toISOString(),
  domain: normalizedDomain,
  intent: body.intent,
  targetWorkflow: routing.workflow,
  priority: routing.priority,
  data: body.data || {},
  metadata: {
    source: body.source || 'api',
    version: '2.0.0',
    environment: process.env.ENVIRONMENT || 'development',
    ...clientInfo
  },
  validation: {
    isValid: true,
    processedAt: new Date().toISOString()
  }
};

// ═══════════════════════════════════════════════════════════════════
// RATE LIMITING CHECK
// ═══════════════════════════════════════════════════════════════════

const request = $input.first().json;
const clientIP = request.metadata?.ip || 'unknown';

// Simple in-memory rate limiting (in production, use Redis)
const rateLimit = {
  maxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 60000
};

// Mock rate limit check (would be Redis-based in production)
const isRateLimited = false; // Replace with actual check

if (isRateLimited) {
  throw new Error('Rate limit exceeded. Please try again later.');
}

return {
  ...request,
  rateLimit: {
    checked: true,
    clientIP: clientIP,
    limitApplied: `${rateLimit.maxRequests} requests per ${rateLimit.windowMs}ms`
  }
};

// Execute SW1_LEADS_COMERCIAL
const input = $input.first().json;

return {
  ...input,
  execution: {
    startTime: new Date().toISOString(),
    workflow: 'SW1_LEADS_COMERCIAL',
    status: 'processing'
  }
};

// Execute SW2_OPERACOES
const input = $input.first().json;

return {
  ...input,
  execution: {
    startTime: new Date().toISOString(),
    workflow: 'SW2_OPERACOES',
    status: 'processing'
  }
};

// Execute SW3_FINANCEIRO
const input = $input.first().json;

return {
  ...input,
  execution: {
    startTime: new Date().toISOString(),
    workflow: 'SW3_FINANCEIRO',
    status: 'processing'
  }
};

// Execute SW4_CONHECIMENTO
const input = $input.first().json;

return {
  ...input,
  execution: {
    startTime: new Date().toISOString(),
    workflow: 'SW4_CONHECIMENTO',
    status: 'processing'
  }
};

// Execute SW5_MONITORAMENTO
const input = $input.first().json;

return {
  ...input,
  execution: {
    startTime: new Date().toISOString(),
    workflow: 'SW5_MONITORAMENTO',
    status: 'processing'
  }
};

// ═══════════════════════════════════════════════════════════════════
// AGGREGATE RESULTS & CALCULATE METRICS
// ═══════════════════════════════════════════════════════════════════

const input = $input.first().json;
const startTime = new Date(input.execution?.startTime || input.timestamp);
const endTime = new Date();
const duration = endTime - startTime;

return {
  requestId: input.requestId,
  domain: input.domain,
  intent: input.intent,
  targetWorkflow: input.targetWorkflow,
  result: {
    status: 'completed',
    processedAt: endTime.toISOString(),
    durationMs: duration,
    durationFormatted: duration > 1000 ? `${(duration/1000).toFixed(2)}s` : `${duration}ms`
  },
  metrics: {
    startTime: startTime.toISOString(),
    endTime: endTime.toISOString(),
    duration: duration
  },
  data: input.data || {}
};

